import { RedisConnectionService } from '@mesx/common-lib';
import { Test, TestingModule } from '@nestjs/testing';
import { AppController } from './app.controller';
import { AppService } from './app.service';

describe('AppController', () => {
  let appController: AppController;

  const mockRedisConnectionFactory = {
    getClient: jest.fn(), // No need to implement since we're not testing probesHealth
  };

  beforeEach(async () => {
    const app: TestingModule = await Test.createTestingModule({
      controllers: [AppController],
      providers: [
        AppService,
        {
          provide: RedisConnectionService,
          useValue: mockRedisConnectionFactory,
        },
      ],
    }).compile();

    appController = app.get<AppController>(AppController);
  });

  describe('root', () => {
    it('should return "mesx/auth-proxy"', () => {
      expect(appController.getHello()).toBe('mesx/auth-proxy');
    });
  });
});

import { Controller, Get, HttpCode } from '@nestjs/common';
import { AppService } from './app.service';

@Controller()
export class AppController {
  public constructor(public readonly appService: AppService) {}

  @Get('/probes/health')
  @HttpCode(200)
  public async probesHealth(): Promise<string> {
    return this.appService.probesHealth();
  }

  @Get()
  public getHello(): string {
    return this.appService.getHello();
  }
}

