import { MiddlewareConsumer, Module, NestModule } from '@nestjs/common';
import { ConfigModule } from '@nestjs/config';
import { AuthMiddleware } from './auth/auth.middleware';
import { AuthModule } from './auth/auth.module';
import { AuthorizationMiddleware } from './auth/authorization.middleware';
import { ProxyMiddleware } from './auth/proxy.middleware';
import { AppLoggerModule } from './common/logger/app-logger.module';
import { NoCacheMiddleware } from './common/middleware/no-cache.middleware';
import { appConfig } from './config/app-config/configuration';
import { AuthConfigModule } from './config/auth/auth-config.module';
import { authConfig } from './config/auth/configuration';
import { CommonConfigModule } from './config/common-config/common-config.module';
import { commonConfiguration } from './config/common-config/configuration';
import { loggerConfig } from './config/logger/configuration';
import { LoggerConfigModule } from './config/logger/logger-config.module';
import { redisSdkConfiguration } from './config/redis/redis-sdk/configuration';
import { RedisSdkCofigModule } from './config/redis/redis-sdk/redis-sdk.module';
import { PlantHryModule } from './helpers/plant-hry/plant-hry.module';
import { RedisProviderModule } from './providers/cache/redis/redis.module';
