@Module({
  controllers: [AppController],
  imports: [
    ConfigModule.forRoot({
      load: [
        appConfig,
        loggerConfig,
        redisSdkConfiguration,
        authConfig,
        commonConfiguration,
      ],
    }),
    AuthModule,
    AppLoggerModule,
    AuthConfigModule,
    LoggerConfigModule,
    RedisProviderModule,
    RedisSdkCofigModule,
    CommonConfigModule,
    PlantHryModule,
  ],
  providers: [AppService],
})
export class AppModule implements NestModule {
  public configure(consumer: MiddlewareConsumer): void {
    consumer
      .apply(
        AuthMiddleware,
        AuthorizationMiddleware,
        ProxyMiddleware,
        NoCacheMiddleware,
      )
      .forRoutes('/');
  }
}

import { RedisConnectionService } from '@mesx/common-lib';
import { Injectable, InternalServerErrorException } from '@nestjs/common';

@Injectable()
export class AppService {
  private readonly message = 'mesx/auth-proxy';

  public constructor(
    private readonly redisConnectionFactory: RedisConnectionService,
  ) {}

  public async probesHealth(): Promise<string> {
    const client = await this.redisConnectionFactory.getClient();

    try {
      if (!client?.isOpen) {
        throw new InternalServerErrorException('Redis client is not connected');
      }

      // Timeout after 2 seconds
      const timeoutPromise = new Promise<void>((_, reject) => {
        setTimeout(() => {
          reject(new Error('Redis ping timed out'));
        }, 2000);
      });

      // Race between Redis ping and timeout
      await Promise.race([client.ping(), timeoutPromise]);

      return this.message;
    } catch (error) {
      throw new InternalServerErrorException(
        `Redis health check failed: ${(error as Error).message}`,
      );
    }
  }

  public getHello(): string {
    return this.message;
  }
}

import { Controller, Get, Query, Req, Res } from '@nestjs/common';
import { Request, Response } from 'express';
import { AuthService } from './auth.service';
import { SessionData } from '@/types/session.types.dto';

@Controller('oauth2')
export class AuthController {
  public constructor(private readonly authService: AuthService) {}

  @Get('login')
  public async login(
    @Req() request: Request,
    @Res() response: Response,
    @Query('state') state?: string,
  ): Promise<void> {
    const redirectUrl = await this.authService.login(request, state);
    response.redirect(redirectUrl);
  }

  @Get('callback')
  public async callback(
    @Req() request: Request,
    @Res() response: Response,
  ): Promise<void> {
    const session = request.session as SessionData;
    const authCallBackResponse: string =
      await this.authService.handleCallback(request);

    session.isAuthenticated = true;

    const redirectUrl =
      authCallBackResponse === undefined
        ? (process.env.ID_PROVIDER_CALLBACK_URL ?? '/')
        : decodeURIComponent(authCallBackResponse);

    response.redirect(redirectUrl);
  }

  @Get('refresh')
  public async refresh(@Req() request: Request): Promise<string | undefined> {
    await this.authService.refreshToken(request);
    const session = request.session as SessionData;
    return session.tokenSet?.access_token;
  }

  @Get('logout')
  public async logout(
    @Req() request: Request,
    @Res() response: Response,
  ): Promise<void> {
    const endSessionUrl = this.authService.getLogoutUrl(request);

    await new Promise<void>((resolve, reject) => {
      request.session.destroy((error) => {
        if (error) reject(error);
        else resolve();
      });
    });

    response.clearCookie('connect.sid');
    response.redirect(endSessionUrl);
  }
}

import { ClientRequest, IncomingMessage } from 'node:http';
import { Request } from 'express';
import type { Response } from 'express';
import { NoCacheHeadersDto } from '@/common/middleware/dto/no-cache-headers.dto';

/**
 * Helper function to merge cookies
 * @param currentCookies - The current cookies from the session
 * @param newCookies - The new cookies from the target server
 * @returns A merged cookie string
 */
function mergeCookies(currentCookies: string, newCookies: string): string {
  const mergedCookieMap = new Map<string, string>();

  for (const cookie of currentCookies.split(';')) {
    const [key, value] = cookie.split('=');
    if (key) mergedCookieMap.set(key.trim(), value?.trim() ?? '');
  }

  for (const cookie of newCookies.split(';')) {
    const [key, value] = cookie.split('=');
    if (key) mergedCookieMap.set(key.trim(), (value ?? '').trim());
  }

  return [...mergedCookieMap].map(([k, v]) => (v ? `${k}=${v}` : k)).join('; ');
}

/**
 * Helper function to set the session cookie in the request header.
 * Reads target cookies from the session (stored in Redis).
 * @param proxyRequest - The outgoing proxy request object
 * @param request - The original incoming request
 */
export function proxyRequestHelper(
  proxyRequest: ClientRequest,
  request: Request,
): void {
  const session = request.session as unknown as
    | Record<string, unknown>
    | undefined;
  const cookie = (session?.targetCookies as string) ?? '';

  if (cookie) {
    proxyRequest.setHeader('Cookie', cookie);
  } else {
    proxyRequest.removeHeader('Cookie');
  }
}

/**
 * Helper function to merge cookies from the target server and store in the session.
 * @param proxyResponse - The proxy response object
 * @param request - The original incoming request
 */
export function proxyResponseHelper(
  proxyResponse: IncomingMessage,
  request: Request,
): void {
  const setCookieHeader = proxyResponse.headers['set-cookie'];
  if (!setCookieHeader || !request.session) return;

  // Clone headers instead of mutating proxyResponse.headers
  const newHeaders = { ...proxyResponse.headers };
  delete newHeaders['set-cookie'];

  const newCookies = Array.isArray(setCookieHeader)
    ? setCookieHeader.map((c) => c.split(';')[0]).join(';')
    : (setCookieHeader as string).split(';')[0];

  const session = request.session as unknown as Record<string, unknown>;
  const currentCookies = (session.targetCookies as string) ?? '';
  session.targetCookies = mergeCookies(currentCookies, newCookies);
}

/**
 * Sets no-cache headers on the given Express response object.
 * @param response The Express response object to set no-cache headers on.
 */
export function setNoCacheHeaders(response: Response): void {
  const noCacheHeaders = new NoCacheHeadersDto();
  for (const [key, value] of Object.entries(noCacheHeaders.headers)) {
    response.setHeader(key, value);
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { Injectable, NestMiddleware } from '@nestjs/common';
import { Request, Response, NextFunction } from 'express';
import { AuthService } from './auth.service';
import {
  BROWSER_REGEX,
  HEALTH_ROOT,
  OAUTH2_ROOT,
} from '@/common/constants/app.constants';
import { AppLogger } from '@/common/logger/app-logger';
import { AuthConfigService } from '@/config/auth/auth-config.service';
import { AuthSession } from '@/types/auth-session.dto';

/**
 * Checks if the provided user agent string matches a known client (browser) user agent.
 * @param userAgent - The user agent string from the request headers.
 * @returns True if the user agent is a browser, false otherwise.
 */
function isBrowserUserAgent(userAgent: string): boolean {
  return BROWSER_REGEX.test(userAgent);
}

/**
 * Handles unauthorized requests by redirecting browsers to login or sending a 401 for other clients.
 * @param request - The incoming HTTP request object.
 * @param response - The HTTP response object used to send redirects or status codes.
 */
function handleUnauthorized(request: Request, response: Response): void {
  const userAgent = request.headers['user-agent'] ?? '';
  if (isBrowserUserAgent(userAgent)) {
    const fullPath = request.originalUrl || request.url; // OriginalUrl keeps query params intact
    const encodedState = encodeURIComponent(fullPath);
    const encodedStateBase64 = Buffer.from(encodedState).toString('base64');
    response.redirect(`${OAUTH2_ROOT}/login?state=${encodedStateBase64}`);
  } else {
    response.status(401).send('Unauthorized');
  }
}

@Injectable()
export class AuthMiddleware implements NestMiddleware {
  public constructor(
    private readonly authService: AuthService,
    private readonly authConfigService: AuthConfigService,
    private readonly logger: AppLogger,
  ) {}

  public async use(
    request: Request & { session: AuthSession },
    response: Response,
    next: NextFunction,
  ): Promise<void> {
    const logContext: JobsLogContext = {
      method: 'use',
      service: AuthMiddleware.name,
    };

    const { session } = request;
    const allowedPaths = [
      OAUTH2_ROOT,
      HEALTH_ROOT,
      ...this.authConfigService.pathToExcludeFromAuth,
    ];
    const authHeader = request.headers['authorization'];

    // Skip middleware for allowed paths
    for (const path of allowedPaths) {
      if (request.path.startsWith(path)) {
        next();
        return;
      }
    }
    try {
      // Session-based authentication
      if (session?.isAuthenticated) {
        await this.authService.refreshToken(request);
        request.headers['x-ms-client-principal'] =
          AuthService.getIdTokenClaimsBase64(session);
      } else if (authHeader) {
        const isValid = await this.authService.isIdTokenActive(request);
        if (!isValid) {
          handleUnauthorized(request, response);
          return;
        }

        const idToken = authHeader.replace('Bearer ', '').trim();
        const [, payload] = idToken.split('.');
        request.headers['x-ms-client-principal'] = payload;

        // No session or token
      } else {
        handleUnauthorized(request, response);
        return;
      }

      next();
    } catch (error) {
      this.logger.error('AuthMiddleware error:', logContext, error);
      handleUnauthorized(request, response);
    }
  }
}

