import { JobsLogContext, RedisConnectionService } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { Request } from 'express';
import { jwtVerify, createRemoteJWKSet } from 'jose';
import { Issuer, generators, Client, TokenSet } from 'openid-client';
import { AuthorizationUrlDto } from './dto/authorization-url.dto';
import { LogoutRequestDto } from './dto/logout-request.dto';
import { OidcClientConfigDto } from './dto/oidc-client-config.dto';
import { RedisLockOptionsDto } from './dto/redis-lock-options.dto';
import { RedisSetExpirationDto } from './dto/redis-set-expiration.dto';
import { TokenSetDto } from './dto/token-set.dto';
import { CallbackOptionsDto } from '@/auth/dto/callback-options.dto';
import {
  OAUTH2_ROOT,
  REDIS_DEFAULT_TTL,
  REDIS_CODE_VERIFIER_TTL,
} from '@/common/constants/app.constants';
import { AppLogger } from '@/common/logger/app-logger';
import { AuthConfigService } from '@/config/auth/auth-config.service';
import { PlantHryService } from '@/helpers/plant-hry/plant-hry.service';
import { UserInfoDto } from '@/types/user-info.dto';

interface SessionWithToken {
  id?: string;
  tokenSet?: TokenSet;
  userInfo?: unknown;
  expiresAt?: number;
}

@Injectable()
export class AuthService {
  public static getIdTokenClaimsBase64(session: SessionWithToken): string {
    return Buffer.from(JSON.stringify(session.userInfo)).toString('base64url');
  }

  public client!: Client;

  // Redis client instance - initialized in onModuleInit for reuse
  private redisClient!: Awaited<
    ReturnType<RedisConnectionService['getClient']>
  >;

  // Cached JWKS fetcher - created once to avoid per-request memory allocation
  private jwks: ReturnType<typeof createRemoteJWKSet> | undefined;

  public constructor(
    private readonly redisConnectionFactory: RedisConnectionService,
    private readonly logger: AppLogger,
    private readonly authConfigService: AuthConfigService,
    private readonly plantHryService: PlantHryService,
  ) {}

  public async onModuleInit(): Promise<void> {
    const logContext: JobsLogContext = {
      method: 'onModuleInit',
      service: AuthService.name,
    };
    this.logger.log('Setting up OIDC client with id Provider...', logContext);

    // Initialize Redis client for reuse across all methods
    this.redisClient = await this.redisConnectionFactory.getClient();
    this.logger.log('Redis client initialized', logContext);

    const issuerUrl = this.authConfigService.idProviderIssuerUrl;
    const clientId = this.authConfigService.idProviderClientId;
    const clientSecret = this.authConfigService.idProviderClientSecret;
    const callbackUrl = this.authConfigService.idProviderCallbackUrl;
    this.logger.log(`Issuer URL: ${issuerUrl}`, logContext);

    const issuer = await Issuer.discover(issuerUrl);
    const oidcClientConfigDto = new OidcClientConfigDto(
      clientId,
      clientSecret,
      [callbackUrl],
      ['code'],
    );
    const clientConfig = {
      ...oidcClientConfigDto,
      scope: 'openid profile email',
    };

    this.client = new issuer.Client(clientConfig);

    // Cache JWKS for token validation - avoids creating new fetcher per request
    const jwksUri = this.client.issuer.metadata.jwks_uri;
    if (jwksUri) {
      this.jwks = createRemoteJWKSet(new URL(jwksUri));
    }

    await this.initPlantUpdates();
  }

  public enrichUser(userInfo: UserInfoDto): {
    groups?: Array<string>;
    assignedPlants: Array<string>;
  } {
    return this.plantHryService.enrichUserInfoWithPlants(userInfo);
  }

  public async initPlantUpdates(): Promise<void> {
    await this.plantHryService.loadPlantHierarchy();
    await this.plantHryService.subscribeToPlantUpdates();
  }

  public async getLoginUrl(): Promise<string> {
    const logContext: JobsLogContext = {
      method: 'getLoginUrl',
      service: AuthService.name,
    };

    this.logger.log('Generating login URL...', logContext);

    const codeVerifier = generators.codeVerifier();
    const codeChallenge = generators.codeChallenge(codeVerifier);
    const state = generators.state();

    // Store code verifier in Redis with TTL to prevent memory leaks
    const redisKey = `oidc:code-verifier:${state}`;
    const ttlOptions = new RedisSetExpirationDto(REDIS_CODE_VERIFIER_TTL);
    await this.redisClient.set(redisKey, codeVerifier, {
      ...ttlOptions,
    });

    const authUrlDto = new AuthorizationUrlDto(
      'openid profile email',
      codeChallenge,
      'S256',
      state,
    );

    return this.client.authorizationUrl({ ...authUrlDto });
  }

  public async refreshToken(request: Request): Promise<void> {
    const logContext: JobsLogContext = {
      method: 'refreshToken',
      service: AuthService.name,
    };
    const session = request.session as SessionWithToken;
    const email = (session.userInfo as { email?: string })?.email;
    const now = Math.floor(Date.now() / 1000);
    if (session.expiresAt && session.expiresAt > now) {
      request.session.touch();
      return;
    }
    if (!email) {
      throw new Error('No email found in session.userInfo');
    }

    const tokenKey = `oidc:tokens:${email}`;
    const lockKey = `${tokenKey}:lock`;

    const lockTTL = 30;
    const redisLockOptionsDto = new RedisLockOptionsDto(lockTTL);
    const refreshInterval =
      await this.authConfigService.getTokenRefreshIntervalSeconds();
    const newExpiresAt = now + refreshInterval;
    const lockAcquired = await this.redisClient.set(
      lockKey,
      '1',
      redisLockOptionsDto.toRedisOptions(),
    );

    if (!lockAcquired) {
      request.session.touch();
      return;
    }

    try {
      const tokenSetJson = await this.redisClient.get(tokenKey);
      if (!tokenSetJson) {
        throw new Error(`No tokenSet found in Redis for user ${email}`);
      }

      const tokenSet: TokenSet = new TokenSet(JSON.parse(tokenSetJson));
      if (!tokenSet.refresh_token) {
        throw new Error(`No refresh token available for user ${email}`);
      }
      let userInfo = session.userInfo ?? {};

      if (tokenSet.expires_at && tokenSet.expires_at > now) {
        if (tokenSet.id_token) {
          const [, payload] = tokenSet.id_token.split('.');
          const claims = JSON.parse(Buffer.from(payload, 'base64').toString());
          userInfo = {
            ...claims,
          };
          userInfo = this.enrichUser(userInfo as UserInfoDto);
          session.userInfo = userInfo;
        }
        session.expiresAt = tokenSet.expires_at + 10;

        request.session.touch();
        return;
      }
      const newTokenSet = await this.client.refresh(tokenSet.refresh_token);
      const tokenDto = new TokenSetDto({
        accessToken: newTokenSet.access_token ?? tokenSet.access_token ?? '',
        expiresAt: newExpiresAt,
        idToken: newTokenSet.id_token ?? tokenSet.id_token ?? '',
        refreshToken: newTokenSet.refresh_token ?? tokenSet.refresh_token ?? '',
        tokenType: newTokenSet.token_type ?? tokenSet.token_type ?? 'Bearer',
      });
      const redisSetExpiration = new RedisSetExpirationDto(REDIS_DEFAULT_TTL);

      if (newTokenSet.id_token) {
        const [, payload] = newTokenSet.id_token.split('.');
        const claims = JSON.parse(Buffer.from(payload, 'base64').toString());
        userInfo = {
          ...claims,
        };

        userInfo = this.enrichUser(userInfo as UserInfoDto);
      }
      session.expiresAt = newExpiresAt;
      session.userInfo = userInfo;
      session.tokenSet = newTokenSet;
      this.logger.debug(`redis tll ${redisSetExpiration.EX}`, logContext);
      await this.redisClient.set(tokenKey, JSON.stringify(tokenDto), {
        ...redisSetExpiration,
      });
    } finally {
      await this.redisClient.del(lockKey);
    }
    request.session.touch();
  }

  public async handleCallback(request: Request): Promise<string> {
    const logContext: JobsLogContext = {
      method: 'handleCallback',
      service: AuthService.name,
    };

    this.logger.log('Handling OIDC callback...', logContext);

    const parameters = this.client.callbackParams(request);
    const [cleanState, query] = (parameters.state || '').split('?');
    parameters.state = cleanState;

    let redirectUrl = '/';
    if (query) {
      const urlSearchParameters = new URLSearchParams(query);
      const encodedState = urlSearchParameters.get('authCallBackResponse');

      redirectUrl = encodedState
        ? Buffer.from(encodedState, 'base64').toString()
        : '/';
    }

    // Retrieve code verifier from Redis
    const redisKey = `oidc:code-verifier:${cleanState}`;
    const codeVerifier = await this.redisClient.get(redisKey);

    if (!codeVerifier) {
      this.logger.error(
        'Invalid or expired state parameter - code verifier not found in Redis',
        logContext,
      );
      return `${OAUTH2_ROOT}/login?state=${redirectUrl}`;
    }

    // Delete immediately after retrieval (single-use token pattern)
    await this.redisClient.del(redisKey);

    const callbackOptionsDto = new CallbackOptionsDto(codeVerifier, cleanState);

    const tokenSet = await this.client.callback(
      this.authConfigService.idProviderCallbackUrl,
      parameters,
      { ...callbackOptionsDto },
    );
    if (!tokenSet.access_token) {
      throw new Error('No access token available — cannot fetch userinfo');
    }
    const userinfo = await this.client.userinfo(tokenSet.access_token);
    let mergedUserInfo = userinfo;
    if (tokenSet.id_token) {
      const [, payload] = tokenSet.id_token.split('.');
      const claims = JSON.parse(Buffer.from(payload, 'base64').toString());
      mergedUserInfo = {
        ...claims,
        ...userinfo,
      };
    }

    // Enrich mergedUserInfo with assigned plants
    const enrichedData = this.enrichUser(mergedUserInfo as UserInfoDto);
    mergedUserInfo = {
      ...mergedUserInfo,
      ...enrichedData,
    };
    const newExpiresAt =
      Math.floor(Date.now() / 1000) +
      (await this.authConfigService.getTokenRefreshIntervalSeconds());
    const tokenDto = new TokenSetDto({
      accessToken: tokenSet.access_token,
      expiresAt: newExpiresAt,
      idToken: tokenSet.id_token,
      refreshToken: tokenSet.refresh_token ?? '',
      tokenType: tokenSet.token_type ?? 'Bearer',
    });

    const session = request.session as SessionWithToken;
    session.userInfo = mergedUserInfo;
    session.tokenSet = tokenSet;
    session.expiresAt = newExpiresAt;

    if (!mergedUserInfo || !mergedUserInfo.email) {
      throw new Error('No email in userinfo — cannot store tokens in Redis');
    }

    // Save tokenSet in Redis under userinfo.email
    const redisSetExpiration = new RedisSetExpirationDto(REDIS_DEFAULT_TTL);
    await this.redisClient.set(
      `oidc:tokens:${userinfo.email}`,
      JSON.stringify(tokenDto),
      {
        ...redisSetExpiration,
      },
    );
    this.logger.log('User authenticated successfully', logContext);

    return redirectUrl;
  }

  public getLogoutUrl(request: Request): string {
    const logContext: JobsLogContext = {
      method: 'getLogoutUrl',
      service: AuthService.name,
    };

    const session = request.session as SessionWithToken;
    if (!session.tokenSet?.id_token) {
      this.logger.error('No id_token in session', logContext);
      throw new Error('No id_token in session');
    }

    this.logger.log('Generating logout URL...', logContext);
    const logoutUrlDto = new LogoutRequestDto(
      session.tokenSet.id_token,
      'http://localhost:3000/logout',
    );
    return this.client.endSessionUrl({ ...logoutUrlDto });
  }

  public async login(request: Request, state?: string): Promise<string> {
    let url = this.authConfigService.idProviderCallbackUrl;
    url = await this.getLoginUrl();
    const encodedState = state ? encodeURIComponent(state) : '';
    return `${url}?authCallBackResponse=${encodedState}`;
  }

  public async isIdTokenActive(request: Request): Promise<boolean> {
    const logContext: JobsLogContext = {
      method: 'isIdTokenActive',
      service: AuthService.name,
    };

    try {
      const authHeader = request.headers['authorization'];
      if (!authHeader || !authHeader.startsWith('Bearer ')) {
        this.logger.warn('No Bearer token found in request', logContext);
        return false;
      }

      const idToken = authHeader.replace('Bearer ', '').trim();

      if (!this.jwks) {
        this.logger.error('JWKS not initialized', logContext);
        return false;
      }

      await jwtVerify(idToken, this.jwks, {
        audience: this.authConfigService.idProviderClientId,
        issuer: this.client.issuer.metadata.issuer,
      });

      return true;
    } catch (error) {
      this.logger.error(
        `Invalid ID token: ${(error as Error).message}`,
        logContext,
      );
      return false;
    }
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { Injectable, NestMiddleware } from '@nestjs/common';
import axios from 'axios';
import { Request, Response, NextFunction } from 'express';
