/**
 * Redirects the user to the appropriate unauthorized page
 * @param path  base app path from the request
 * @param response The outgoing Express response object.
 */
function redirectToUnauthorized(path: string, response: Response): void {
  const segments = path.split('/');
  const basePath = segments.length > 1 ? `/${segments[1]}` : '';
  response.redirect(`${basePath}/unauthorized`);
}

@Injectable()
export class AuthorizationMiddleware implements NestMiddleware {
  public constructor(
    private readonly commonConfigService: CommonConfigService,
    private readonly logger: AppLogger,
  ) {}

  public async use(
    request: Request & { session: AuthSession },
    response: Response,
    next: NextFunction,
  ): Promise<void> {
    try {
      const logContext: JobsLogContext = {
        method: 'use',
        service: AuthorizationMiddleware.name,
      };
      // Only protect /ui routes
      if (
        !request.path.includes('-ui') ||
        request.path.endsWith('unauthorized') ||
        request.path.includes('-ui/assets')
      ) {
        next();
        return;
      }
      const { session } = request;
      const email = session?.userInfo?.email;
      const userRoles: Array<string> = session?.userInfo?.groups || [];

      // Normalize LDAP roles (CN=xxxx)
      const cleanedRoles = userRoles.map((role) =>
        role.startsWith('CN=')
          ? role.split(',')[0].replace('CN=', '').trim()
          : role.trim(),
      );

      // Get exception roles dynamically from app config
      const exceptionRolesString =
        await this.commonConfigService.getExceptionRoles();
      const exceptionRoles =
        exceptionRolesString?.split(';').map((r) => r.trim()) ?? [];

      // Skip authorization if user is in exception roles
      const isExceptionUser = cleanedRoles.some((role) =>
        exceptionRoles.includes(role),
      );
      this.logger.log(`Is exception user: ${isExceptionUser}`, logContext);
      if (isExceptionUser) {
        next();
        return;
      }

      if (!email) {
        redirectToUnauthorized(request.path, response);
        return;
      }

      const token = process.env.TOKEN;
      let plantValue: string | null;

      try {
        const plantResponse = await axios.get(
          `${this.commonConfigService.umeApiAppId}/user-attribute-mapping/getPlantByEmail`,
          {
            headers: { authorization: `Bearer ${token}` },
            params: { email },
          },
        );
        plantValue = plantResponse.data;
        this.logger.debug(`Fetched plant value: ${plantValue}`, logContext);
      } catch (error) {
        this.logger.error('Error fetching plant value:', logContext, error);
        redirectToUnauthorized(request.path, response);
        return;
      }

      const assignedPlants: Array<string> =
        session?.userInfo?.assignedPlants || [];
      this.logger.debug(`Assigned plants: ${assignedPlants}`, logContext);

      if (plantValue && !assignedPlants.includes(plantValue)) {
        redirectToUnauthorized(request.path, response);
        return;
      }

      next();
    } catch (error) {
      console.error('AuthorizationMiddleware error:', error);
      redirectToUnauthorized(request.path, response);
    }
  }
}

