import { Injectable, NestMiddleware } from '@nestjs/common';
import { Request, Response, NextFunction } from 'express';
import { createProxyMiddleware, Options } from 'http-proxy-middleware';

import {
  proxyRequestHelper,
  proxyResponseHelper,
  setNoCacheHeaders,
} from './auth.helper';
import { NEST_APP_LOCAL_PATHS } from '@/common/constants/app.constants';
import { AuthConfigService } from '@/config/auth/auth-config.service';

@Injectable()
export class ProxyMiddleware implements NestMiddleware {
  private readonly proxy;

  public constructor(private readonly authConfigService: AuthConfigService) {
    const rootPath = '^/';
    const proxyOptions: Options = {
      changeOrigin: true,
      on: {
        proxyReq: (proxyRequest, request: Request) => {
          proxyRequestHelper(proxyRequest, request);
        },
        proxyRes: (proxyResponse, request: Request, response: Response) => {
          setNoCacheHeaders(response);
          proxyResponseHelper(proxyResponse, request);
        },
      },
      pathRewrite: { [rootPath]: '/' },
      selfHandleResponse: false,
      target: this.authConfigService.proxyTargetUrl,
    };

    this.proxy = createProxyMiddleware(proxyOptions);
  }

  public use(request: Request, response: Response, next: NextFunction): void {
    for (const path of NEST_APP_LOCAL_PATHS) {
      if (request.path.startsWith(path)) {
        next();
        return;
      }
    }

    this.proxy(request, response, next);
  }
}

