import { RedisConnectionService } from '@mesx/common-lib';
import { Injectable, Logger, OnModuleDestroy } from '@nestjs/common';
import axios from 'axios';
import { CommonConfigService } from '@/config/common-config/common-config.service';

import { RedisConfigService } from '@/config/redis/redis-sdk/redis-sdk.service';

interface Plant {
  sid: string;
  plantId: string;
}

@Injectable()
export class PlantHryService implements OnModuleDestroy {
  private readonly logger = new Logger(PlantHryService.name);

  private plantsCache: Map<string, string> = new Map();

  private subscriber: Awaited<
    ReturnType<RedisConnectionService['getClient']>
  > | null = null;

  public constructor(
    private readonly redisConfigService: RedisConfigService,
    private readonly commonConfigService: CommonConfigService,
    private readonly redisConnectionFactory: RedisConnectionService,
  ) {}

  public async onModuleDestroy(): Promise<void> {
    if (this.subscriber) {
      await this.subscriber.unsubscribe('plants-updated');
      this.subscriber.destroy();
      this.subscriber = null;
    }
    this.plantsCache.clear();
  }

  // -----------------------------
  // Load plants from Redis or API
  // -----------------------------
  public async loadPlantHierarchy(): Promise<void> {
    const logContext = {
      method: 'loadPlantHierarchy',
      service: PlantHryService.name,
    };

    const redisClient = await this.redisConnectionFactory.getClient();
    const plantHryRedisKey = 'plant-hierarchy-api-plant';
    const authProxyRedisKey = this.redisConfigService.redisPlantKey;

    try {
      const plantHash = await redisClient.hGetAll(plantHryRedisKey);
      let plants: Array<Plant> = [];

      if (plantHash?.plants) {
        plants = JSON.parse(plantHash['plants']);
        this.logger.log('Loaded plants from Plant-Hry Redis hash', logContext);
      } else {
        this.logger.warn(
          'Plant-Hry Redis empty → fetching via API',
          logContext,
        );

        const response = await axios.get(
          `${this.commonConfigService.plantHierarchyApiAppId}/plant/Plants`,
        );
        plants = response.data;
        this.logger.log('Fetched plants via API', logContext);

        await redisClient.hSet(
          authProxyRedisKey,
          'plants',
          JSON.stringify(plants),
        );
      }

      this.plantsCache = new Map(
        plants.filter((p) => p.sid).map((p) => [p.sid, p.plantId]),
      );
      this.logger.log(
        `plantsCache created with ${this.plantsCache.size} entries`,
        logContext,
      );
    } catch (error) {
      this.logger.error('Failed to load plant hierarchy', logContext, error);
    }
  }

  // -----------------------------
  // Subscribe to Redis updates
  // -----------------------------
  public async subscribeToPlantUpdates(): Promise<void> {
    const logContext = {
      method: 'subscribeToPlantUpdates',
      service: PlantHryService.name,
    };
    const redisClient = await this.redisConnectionFactory.getClient();
    this.subscriber = redisClient.duplicate();
    await this.subscriber.connect();

    await this.subscriber.subscribe(
      'plants-updated',
      async (message: string) => {
        try {
          const event = JSON.parse(message);
          this.logger.log(
            `Received plant update event: ${message}`,
            logContext,
          );

          await this.loadPlantHierarchy();

          this.logger.log(
            `plantsCache updated after '${event.action}' event, total entries: ${this.plantsCache.size}`,
            logContext,
          );
        } catch (error) {
          this.logger.error('Failed to process plant update event', error);
        }
      },
    );
  }

  // -----------------------------
  // Enrich user info with assigned plants
  // -----------------------------
  public enrichUserInfoWithPlants(userInfo: {
    groups?: Array<string>;
    assignedPlants?: Array<string>;
  }): { groups?: Array<string>; assignedPlants: Array<string> } {
    const groups = userInfo.groups ?? [];
    if (groups.length === 0) return { ...userInfo, assignedPlants: [] };

    const assignedPlants = new Set<string>();
    for (const group of groups) {
      const sid = group.slice(-3);
      const plantId = this.plantsCache.get(sid);
      if (plantId) assignedPlants.add(plantId);
    }

    return { ...userInfo, assignedPlants: [...assignedPlants] };
  }

  // -----------------------------
  // Optional: Getter for plantsCache
  // -----------------------------
  public getPlantsCache(): Map<string, string> {
    return this.plantsCache;
  }
}

