import { randomInt } from 'node:crypto';
import { JobsLogContext } from '@mesx/common-lib';
import { ExponentialBackoffRetryDto } from './dtos/exponential-backoff-retry.dto'; // Path to your DTO
import { AppLogger } from '@/common/logger/app-logger';

/**
 * Calculates the delay for the next retry attempt using exponential backoff with a random jitter.
 * @param attempt - The current attempt number.
 * @param maxBackoff - The maximum backoff time in seconds.
 * @returns The calculated delay in milliseconds.
 */
export function calculateExponentialBackoffDelay(
  attempt: number,
  maxBackoff: number,
): number {
  const randomNumberMilliseconds = randomInt(0, 1000); // Random number between 0 and 1000
  const exponentialDelay = 2 ** attempt; // 2^n
  return Math.min(
    exponentialDelay * 1000 + randomNumberMilliseconds,
    maxBackoff * 1000,
  ); // Convert seconds to milliseconds
}

/**
 * Retries a given operation a specified number of times with an exponential backoff delay between attempts.
 * @template T The type of the result returned by the operation.
 * @param logger - Logger instance for logging.
 * @param context - Job Log Context.
 * @param operation - The operation to retry.
 * @param options - Options object containing the parameters for the backoff retry, such as retries, baseDelayMs, jitter, attempt, and maxBackoff.
 * @returns A promise that resolves to the result of the operation.
 * @throws Will throw an error if the operation fails after the specified number of retries.
 */
export async function exponentialBackoffRetry<T>(
  logger: AppLogger,
  context: JobsLogContext,
  operation: () => Promise<T>,
  options: ExponentialBackoffRetryDto, // Using DTO here
): Promise<T> {
  const {
    retries = 5,
    baseDelayMs = 1000,
    jitter = true,
    attempt = 1,
    maxBackoff = 32,
  } = options; // Destructure the options DTO
  try {
    return await operation();
  } catch (error) {
    const isRetryableError =
      // If Redis returns a 5xx-like error (this would depend on the client you're using)
      error.code === 429 ||
      (error.code >= 500 && error.code < 600) ||
      error.message.includes('The client is closed') ||
      // Network or connection errors (Socket closed in case of redis infra redeploy)
      error.message.includes('Socket closed unexpectedly') ||
      // Network or connection errors (AbortError)
      error.name === 'AbortError' ||
      // Redis errors that indicate retryable conditions
      (error.name === 'ReplyError' &&
        (error.message.includes('TRYAGAIN') ||
          error.message.includes('READONLY')));
    if (!isRetryableError) {
      logger.error(
        `Non-retryable error encountered: ${(error as Error).message}`,
        context,
      );
      throw error; // Non-retryable error, rethrow
    }

    if (attempt >= retries) {
      logger.error(
        `Operation failed after ${retries} retries: ${(error as Error).message}`,
        context,
      );
      throw error;
    }
    // Calculate delay
    const delay = jitter
      ? calculateExponentialBackoffDelay(attempt, maxBackoff)
      : baseDelayMs * 2 ** (attempt - 1);

    await new Promise((resolve) => {
      setTimeout(resolve, delay);
    });
    return exponentialBackoffRetry(logger, context, operation, {
      ...options,
      attempt: attempt + 1,
    });
  }
}

import { RedisConnectionService } from '@mesx/common-lib';
import { ValidationPipe } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { RedisStore } from 'connect-redis';
import type { Request, Response, NextFunction } from 'express';
import * as express from 'express';
import * as session from 'express-session';
import * as passport from 'passport';

import { NEST_APP_LOCAL_PATHS } from './common/constants/app.constants';
import { AuthConfigService } from './config/auth/auth-config.service';
import { AppModule } from '@/app.module';
import { UserInfo } from '@/types/session.types.dto';

/**
 * Bootstrap the NestJS application.
 * This function initializes the app with global validation pipes,
 * sets up Redis-backed session management, initializes Passport for
 * authentication, configures CORS, and starts the server.
 * @returns A promise that resolves when the server is running.
 */
async function bootstrap(): Promise<void> {
  const app = await NestFactory.create(AppModule, { bodyParser: false });

  app.useGlobalPipes(
    new ValidationPipe({
      forbidNonWhitelisted: true,
      transform: true,
      whitelist: true,
    }),
  );
  const jsonParser = express.json();

  app.use((request: Request, resource: Response, next: NextFunction): void => {
    if (
      NEST_APP_LOCAL_PATHS.some((prefix) => request.path.startsWith(prefix))
    ) {
      return jsonParser(request, resource, next);
    }
    return next();
  });
  const redisFactory = app.get(RedisConnectionService);
  const redisClient = await redisFactory.getClient();
  const authConfigService = app.get(AuthConfigService);
  const cookieExpirationMs =
    (await authConfigService.cookieExpirationSeconds()) * 1000;
  const redisStore = new RedisStore({
    client: redisClient,
  });
  app.use(
    session({
      cookie: {
        httpOnly: true,
        maxAge: cookieExpirationMs,
        sameSite: 'lax',
      },
      resave: false,
      rolling: true,
      saveUninitialized: false,
      secret: process.env.SESSION_SECRET ?? 'your-secret-key',
      store: redisStore, // Pass the instance directly
    }),
  );

  app.use(passport.initialize());
  app.use(passport.session());
  passport.serializeUser((user: UserInfo, done) => done(undefined, user));
  passport.deserializeUser((user: unknown, done) =>
    done(undefined, user as UserInfo | false | null),
  );

  app.enableCors({
    allowedHeaders: 'Content-Type,Authorization',
    credentials: true,
    origin: process.env.ORIGINS_TO_ALLOW_CORS,
  });

  await app.listen(process.env.APP_PORT || 3000);
}

bootstrap();

