  sub: string;
  groups: Array<string>;
  given_name: string;
  family_name: string;
  email: string;
}

// Extend Express session with user info
export interface SessionWithUser {
  id: string;
  cookie: CookieInfo;
  userInfo?: UserInfo;
  [key: string]: unknown; // For any other session properties
}

// Extend Request to include typed session
export type RequestWithUser = Request & {
  session: SessionWithUser;
};

